import 'dart:io';
import 'dart:isolate';

class FileSystemIndexer {
  /// Traverses project directory in a dedicated background isolate
  static Future<List<ProjectNode>> indexWorkspace(String rootPath) async {
    final receivePort = ReceivePort();

    await Isolate.spawn(_backgroundWorker, {
      'sendPort': receivePort.sendPort,
      'root': rootPath,
    });

    final result = await receivePort.first as List<ProjectNode>;
    return result;
  }

  static void _backgroundWorker(Map<String, dynamic> params) {
    final sendPort = params['sendPort'] as SendPort;
    final rootDir = Directory(params['root'] as String);

    final nodes = <ProjectNode>[];
    if (rootDir.existsSync()) {
      for (final entity in rootDir.listSync(recursive: false, followLinks: false)) {
        nodes.add(ProjectNode(
          path: entity.path,
          name: entity.uri.pathSegments.reversed.skip(1).first,
          isDirectory: entity is Directory,
        ));
      }
    }

    sendPort.send(nodes);
  }
}

