typedef CreatePseudoConsoleC = Int32 Function(
  COORD size,
  IntPtr hInput,
  IntPtr hOutput,
  Uint32 dwFlags,
  Pointer<IntPtr> phPC,
);

typedef CreatePseudoConsoleDart = int Function(
  COORD size,
  int hInput,
  int hOutput,
  int dwFlags,
  Pointer<IntPtr> phPC,
);

final DynamicLibrary kernel32 = DynamicLibrary.open('kernel32.dll');
final CreatePseudoConsoleDart createPseudoConsole = kernel32
    .lookup<NativeFunction<CreatePseudoConsoleC>>('CreatePseudoConsole')
    .asFunction();

import 'dart:convert';

class AgentTool {
  final String name;
  final String description;
  final Map<String, dynamic> parametersSchema;
  final Future<String> Function(Map<String, dynamic> args) handler;

  AgentTool({
    required this.name,
    required this.description,
    required this.parametersSchema,
    required this.handler,
  });
}

// Example: Tool that searches local SQLite database
final searchNotesTool = AgentTool(
  name: 'search_local_notes',
  description: 'Searches user private notes database by query string',
  parametersSchema: {
    'type': 'object',
    'properties': {
      'query': {'type': 'string', 'description': 'The keyword to search'},
    },
    'required': ['query'],
  },
  handler: (args) async {
    final query = args['query'] as String;
    final results = await LocalDatabase.instance.searchNotes(query);
    return jsonEncode(results);
  },
);
